def scope_existing_tags(apps, schema_editor):
    alias = schema_editor.connection.alias
    for prefix in ("Article", "Journal", "Note", "CentralPoint", "Strategy", "Decision", "Goal"):
        Record = apps.get_model("core", prefix)
        Tag = apps.get_model("core", prefix + "Tag")
        Category = apps.get_model("core", prefix + "Category")
        relation = Record._meta.get_field("tags").remote_field.through
        record_field = Record._meta.model_name + "_id"
        tag_field = Tag._meta.model_name + "_id"
        for tag in Tag.objects.using(alias).all().iterator():
            links = list(relation.objects.using(alias).filter(**{tag_field: tag.pk}))
            scopes = {}
            for link in links:
                record = Record.objects.using(alias).get(pk=getattr(link, record_field))
                category_id = record.category_id
                if category_id is None:
                    category, _ = Category.objects.using(alias).get_or_create(
                        user_id=record.user_id, slug="uncategorized", defaults={"name": "Uncategorized"}
                    )
                    category_id = category.pk
                    Record.objects.using(alias).filter(pk=record.pk).update(category_id=category_id)
                key = (record.user_id, category_id, record.subcategory_id)
                scopes.setdefault(key, []).append(link)
            if not scopes:
                category, _ = Category.objects.using(alias).get_or_create(
                    user_id=tag.user_id, slug="uncategorized", defaults={"name": "Uncategorized"}
                )
                scopes[(tag.user_id, category.pk, None)] = []
            original_slug = tag.slug
            for index, ((user_id, category_id, subcategory_id), scope_links) in enumerate(scopes.items()):
                if index == 0:
                    scoped = tag
                    scoped.user_id = user_id
                    scoped.category_id = category_id
                    scoped.subcategory_id = subcategory_id
                    scoped.save(using=alias)
                else:
                    base = original_slug[:35] or "tag"
                    suffix = 2
                    slug = f"{base}-{suffix}"
                    while Tag.objects.using(alias).filter(user_id=user_id, slug=slug).exists():
                        suffix += 1
                        slug = f"{base}-{suffix}"
                    scoped = Tag.objects.using(alias).create(
                        user_id=user_id, name=tag.name, slug=slug,
                        category_id=category_id, subcategory_id=subcategory_id,
                    )
                    for link in scope_links:
                        relation.objects.using(alias).filter(pk=link.pk).update(**{tag_field: scoped.pk})


